'use strict';
const AUTHOR_GITHUB_URL='https://github.com/ruiyingyang-ryyang';
let weeklyFrom='',weeklyTo='',weeklyWeek='',weeklySelected=new Set(),preferenceTimer,pendingAppearance=null,appearanceRevision=0,balances=null,balanceBusy=false,balanceError='';
const moreLabels={zh:{appearance:'显示设置',theme:'主题',light:'日间',dark:'夜间',font:'字号',reset:'清空并重新开始',resetHelp:'清空本机论文、收藏、标签、运行记录、推送记录、设置和对话，停用定时推送。保留 DeepSeek / GPT / SerpApi 密钥和连接模型，不会更改服务商账户、用量或账单。已导出的文件不会删除。',resetConfirm:'确认清空，保留 API',authorOptional:'作者姓名（选填）',schoolOptional:'学校 / 机构（选填）',authorConfigHelp:'填写作者后，可检索其第一作者或通讯作者论文；留空则仅按关键词检索。不填写学校可能包含同名作者。',years:'发表年份限制',fromYear:'起始年份',toYear:'结束年份',yearHelp:'留空不限制；填写后只收录范围内的论文。',weeklyPolicy:'仅推送推送日前 7 个自然日发表的论文（不含推送当天）；不推送更早、缺少确切日期或已经推送过的论文。',weeklyGrouping:'按推送周归纳',allWeeks:'全部周',fromDate:'推送日期起',toDate:'推送日期止',selectAll:'选择当前范围',exportMD:'归纳并批量导出 MD',exportTitle:'导出每周论文',useAI:'使用所选 AI 接口按研究主题归纳',exportHelp:'每周生成一个 Markdown 文件，并附目录。关闭 AI 归纳后，按周整理论文、作者、期刊和摘要，不调用 API。',exportNow:'选择文件夹并导出',selected:'已选',papersUnit:'篇',exported:'导出完成',unknownWeek:'早期记录 · 未记录推送周',corrShort:'通讯',firstShort:'首作',range:'日期范围',stopExport:'停止导出'},en:{appearance:'Appearance',theme:'Theme',light:'Light',dark:'Dark',font:'Text size',reset:'Start over',resetHelp:'Clear local papers, stars, tags, runs, digest records, settings and conversations, and disable the schedule. Keep DeepSeek / GPT / SerpApi keys and the connection model. Provider accounts, usage, billing and exported files remain intact.',resetConfirm:'Clear data, keep APIs',authorOptional:'Author name (optional)',schoolOptional:'Institution (optional)',authorConfigHelp:'An author name finds papers with an explicit first/corresponding role. Leave blank for keyword searches. Add an institution to distinguish namesakes.',years:'Publication year range',fromYear:'From year',toYear:'To year',yearHelp:'Leave blank for no limit. Only papers in the chosen years are collected.',weeklyPolicy:'Only papers published during the 7 complete calendar days before the push date, excluding the push day. Older, undated or previously delivered papers are excluded.',weeklyGrouping:'Grouped by delivery week',allWeeks:'All weeks',fromDate:'Delivered from',toDate:'Delivered through',selectAll:'Select this range',exportMD:'Summarize & export MD',exportTitle:'Export weekly papers',useAI:'Summarize research themes with the selected AI',exportHelp:'Create one Markdown file per week plus an index. Turn off AI summaries to organize papers, authors, journals and abstracts without an API request.',exportNow:'Choose folder & export',selected:'Selected',papersUnit:'papers',exported:'Export complete',unknownWeek:'Legacy records · week unavailable',corrShort:'Corr.',firstShort:'First',range:'Date range',stopExport:'Stop export'}};

Object.assign(moreLabels.zh,{font:'字号',resetShort:'重新开始',fromYear:'起始年月',toYear:'结束年月',yearHelp:'留空不限制；填写后只收录范围内的论文，缺少发表月份的候选排除。',authorOptional:'作者姓名（可填多个）',schoolOptional:'学校 / 机构（可填多个，选填）',authorConfigHelp:'多个姓名或机构用分号或换行分隔，各最多 10 个。匹配任一作者与任一机构；机构留空则不限制。仍需来源明确标注第一作者或通讯作者。',balance:'API 用量与余量',refreshBalance:'刷新余量',balanceHelp:'查询已保存密钥所属账户的余额或剩余检索次数，不发起论文检索或模型对话。',noSavedKey:'未保存密钥',checking:'正在查询…',searchesLeft:'剩余检索次数',available:'账户可用',unavailable:'当前余额不可用',checked:'查询时间',deleteChat:'删除对话',deleteQuestion:'删除此问题',deleteChatHelp:'删除这条对话及其中的全部问题和回答。',deleteQuestionHelp:'删除这个问题及对应回答，保留本对话的其他内容。',delete:'确认删除'});
Object.assign(moreLabels.en,{font:'Text size',resetShort:'Start over',fromYear:'From month',toYear:'Through month',yearHelp:'Leave blank for no limit. Papers without a known publication month are excluded when a range is set.',authorOptional:'Author names (multiple)',schoolOptional:'Institutions (multiple, optional)',authorConfigHelp:'Separate names or institutions with semicolons or new lines, up to 10 each. Match any author and any institution. Leave institutions blank for no limit. Explicit first/corresponding roles are required.',balance:'API usage & balance',refreshBalance:'Refresh balance',balanceHelp:'Query saved accounts for balance and remaining searches without a model conversation or paper search.',noSavedKey:'No saved key',checking:'Checking…',searchesLeft:'Searches remaining',available:'Account available',unavailable:'Balance unavailable',checked:'Last checked',deleteChat:'Delete conversation',deleteQuestion:'Delete question',deleteChatHelp:'Delete this conversation and all its questions and answers.',deleteQuestionHelp:'Delete this question and its answer. Keep the rest of the conversation.',delete:'Delete'});

const u=k=>moreLabels[state?.settings.language||'zh'][k]||k;
function appearance(){return state.settings.appearance||{theme:'light',fontSize:13};}
function applyAppearance(){const p=appearance();document.documentElement.dataset.theme=p.theme==='dark'?'dark':'light';document.documentElement.style.setProperty('--app-font',Math.max(11,Math.min(20,p.fontSize||13))+'px');}
async function saveAppearance(value){if(editingSettings())draft=capture();const revision=++appearanceRevision;pendingAppearance={...appearance(),...value};state.settings.appearance={...pendingAppearance};applyAppearance();const result=await call('appearance',{...pendingAppearance});if(revision===appearanceRevision){pendingAppearance=null;if(result&&result.settings)state=normalState(result);}}
function appearancePanel(){return '<section class="appearance-panel"><label class="appearance-row" for="font-size"><span>'+u('font')+'</span><output id="font-value" for="font-size">'+(appearance().fontSize||13)+'</output></label><input id="font-size" type="range" min="11" max="20" step="1" value="'+(appearance().fontSize||13)+'" aria-label="'+u('font')+'"><div class="font-endpoints"><span>11</span><span>20</span></div></section>';}
function authorConfig(s){return `<section class="panel author-config"><h2>${t('authorLookup')}</h2><p class="help">${u('authorConfigHelp')}</p><label for="settings-author-name">${u('authorOptional')}</label><textarea id="settings-author-name" rows="2" maxlength="1200" placeholder="${u('authorOptional')}">${esc(s.authorName||'')}</textarea><div class="field"><label for="settings-author-school">${u('schoolOptional')}</label><textarea id="settings-author-school" rows="2" maxlength="2200" placeholder="${u('schoolOptional')}">${esc(s.authorSchool||'')}</textarea></div><div class="field"><label for="settings-author-role">${t('authorRole')}</label><select id="settings-author-role">${option('either',t('eitherRole'),s.authorRole||'either')}${option('first',t('first'),s.authorRole)}${option('corresponding',t('corr'),s.authorRole)}</select></div>${view==='settings'?`<div class="year-range">${monthField('month-from',u('fromYear'),s.monthFrom??(s.yearFrom?s.yearFrom+'-01':''))}${monthField('month-to',u('toYear'),s.monthTo??(s.yearTo?s.yearTo+'-12':''))}</div><p class="help">${u('yearHelp')}</p>`:`<p class="weekly-policy">${u('weeklyPolicy')}</p>`}</section>`;}

function delivery(p){if(p.weeklyDeliveries?.length)return [...p.weeklyDeliveries].sort((a,b)=>a.at-b.at)[0];const r=state.runs.filter(r=>r.scheduled&&p.weeklyRuns?.includes(r.id)).sort((a,b)=>a.startedAt-b.startedAt)[0];if(r){const d=new Date(r.startedAt);d.setDate(d.getDate()-(d.getDay()+6)%7);return {at:r.startedAt,week:ymd(d)};}return {at:0,week:'unknown'};}
function ymd(value){const d=new Date(value);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function weekLabel(week){if(!/^\d{4}-\d{2}-\d{2}$/.test(week))return u('unknownWeek');const end=new Date(week+'T12:00:00');end.setDate(end.getDate()+6);return week+' — '+ymd(end);}
function weeklyMatches(p){if(view!=='weekly')return true;const d=delivery(p),day=d.at?ymd(d.at):'';return (!weeklyFrom||day>=weeklyFrom)&&(!weeklyTo||!!day&&day<=weeklyTo)&&(!weeklyWeek||d.week===weeklyWeek);}
function weeklyTools(){const weeks=[...new Set(state.papers.filter(weeklyPaper).map(p=>delivery(p).week))].sort().reverse();return `<section class="weekly-tools"><div class="weekly-range"><label>${u('weeklyGrouping')}<select id="week-filter">${option('',u('allWeeks'),weeklyWeek)}${weeks.map(w=>option(w,weekLabel(w),weeklyWeek)).join('')}</select></label>${dateField('weekly-from',u('fromDate'),weeklyFrom)}${dateField('weekly-to',u('toDate'),weeklyTo)}</div><div class="weekly-actions"><span id="weekly-selected-count">${u('selected')} ${weeklySelected.size} ${u('papersUnit')}</span>${btn('weekly-select-all',u('selectAll'),'check','small')}${btn('weekly-export',u('exportMD'),'download','primary small')}${state.activeAi.includes('weekly-export')?btn('cancel-ai',u('stopExport'),'close','small','data-id="weekly-export"'):''}</div></section>`;}
function weeklyCards(list){const groups=new Map();for(const p of list){const w=delivery(p).week;if(!groups.has(w))groups.set(w,[]);groups.get(w).push(p);}return [...groups].sort(([a],[b])=>b.localeCompare(a)).map(([w,papers])=>`<section class="weekly-group"><div class="weekly-group-title">${esc(weekLabel(w))}<span>${papers.length}</span></div>${papers.map(card).join('')}</section>`).join('');}
function resetSession(){reset101();writingDraft=null;writingBusy=false;selected=null;draft=null;view='inbox';chatId=null;chatInput='';chatSearch='';chatTargetMessage=null;chatSending=false;filter='';groupFilter='';authorFilter='';tagFilter='';journalFilter='';activeAuthorQuery=null;authorQuery={name:'',school:'',role:'either'};authorOpen=false;weeklySelected.clear();weeklyFrom=weeklyTo=weeklyWeek='';abstractModes={};abstractBusy.clear();page=0;modal=null;}
function authorFeedbackHTML(){return `<p class="field">${wx('是否前往作者的 GitHub 主页？','Open the author’s GitHub profile?')}</p><p class="feedback-homepage">${AUTHOR_GITHUB_URL}</p><p class="help feedback-network-note">${wx('访问 GitHub 可能需要科学上网。','Accessing GitHub may require a VPN or proxy, depending on your network.')}</p><div class="row modal-actions">${btn('modal-close',t('cancel'))}${btn('confirm-author-feedback',wx('确认跳转','Open GitHub'),'external','primary')}</div>`;}
function controlsModal(){let content='',title='';if(modal.kind==='author-feedback'){title=wx('问题反馈','Feedback');content=authorFeedbackHTML();}if(modal.kind==='appearance'){title=u('appearance');content=appearancePanel();}if(modal.kind==='date-picker'){title=u(modal.field==='weekly-from'?'fromDate':'toDate');content=datePicker();}if(modal.kind==='month-picker'){title=modal.field==='month-from'?u('fromYear'):u('toYear');content=monthPicker();}if(modal.kind==='reset'){title=u('reset');content=`<p class="reset-description">${u('resetHelp')}</p><div class="row modal-actions">${btn('modal-close',t('cancel'))}${btn('reset-confirm',u('resetConfirm'),'refresh','primary')}</div>`;}if(modal.kind==='balance'){title=u('balance');content=balanceHTML();}if(modal.kind==='chat-delete'){title=u(modal.messageId?'deleteQuestion':'deleteChat');content='<p class="reset-description">'+u(modal.messageId?'deleteQuestionHelp':'deleteChatHelp')+'</p><div class="row modal-actions">'+btn('modal-close',t('cancel'))+btn('delete-chat-confirm',u('delete'),'trash','primary')+'</div>';}if(modal.kind==='weekly-export'){title=u('exportTitle');content=`<p class="help">${u('exportHelp')}</p><p>${u('selected')} ${weeklySelected.size} ${u('papersUnit')}</p><label class="checkbox field"><input id="export-ai" type="checkbox" ${hasAIKey()?'checked':''}>${u('useAI')}</label><div class="row modal-actions">${btn('modal-close',t('cancel'))}${btn('export-weekly-confirm',u('exportNow'),'download','primary')}</div>`;}return `<div class="modal-backdrop" data-action="modal-backdrop"><section class="modal ${modal.kind==='balance'?'balance-modal':modal.kind==='date-picker'?'date-picker-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="row between modal-header"><h2 id="modal-title">${title}</h2>${btn('modal-close','','close','ghost icon',`id="modal-close" aria-label="${t('close')}"`)}</div>${content}</section></div>`;}
async function additionalAction(a,b){
 if(a==='author-feedback'){openModal({kind:'author-feedback'});return true;}
 if(a==='confirm-author-feedback'){
  if(modal?.kind!=='author-feedback')return true;
  b.disabled=true;
  try{await call('open-external',AUTHOR_GITHUB_URL);closeModal();}catch(error){b.disabled=false;throw error;}
  return true;
 }
 if(a==='toggle-tools'){const current=view,collapsed=!toolsCollapsed();state.settings.panelsCollapsed={...state.settings.panelsCollapsed,[current]:collapsed};render();const result=await call('workspace-panel',{view:current,collapsed});if(result?.settings)state=normalState(result);return true;}


 if(a==='choose-date'){
  if(!['weekly-from','weekly-to'].includes(b.dataset.field))return true;
  const value=b.dataset.value||ymd(new Date()),[year,month,day]=value.split('-').map(Number);openModal({kind:'date-picker',field:b.dataset.field,year,month,day,focusId:b.id});return true;
 }
 if(a==='date-month-prev'||a==='date-month-next'){const date=new Date(modal.year,modal.month-1+(a==='date-month-prev'?-1:1),1);if(updatePickerMonth(date.getFullYear(),date.getMonth()+1))render();return true;}
 if(a==='date-pick-day'){modal.day=Number(b.dataset.day);for(const day of $$('.date-day')){const active=Number(day.dataset.day)===modal.day;day.classList.toggle('is-selected',active);day.setAttribute('aria-pressed',String(active));}return true;}
 if(a==='apply-date'||a==='clear-date'){
  if(a==='apply-date'&&!updatePickerMonth(Number($('#date-picker-year').value),Number($('#date-picker-month').value)))throw Error('INVALID_DATE');
  const value=a==='clear-date'?'':modal.year+'-'+String(modal.month).padStart(2,'0')+'-'+String(modal.day).padStart(2,'0');
  if(modal.field==='weekly-from')weeklyFrom=value;else weeklyTo=value;selected=null;page=0;closeModal();return true;
 }
 if(a==='choose-month'){openModal({kind:'month-picker',field:b.dataset.field,value:b.dataset.value});return true;}
 if(a==='apply-month'||a==='clear-month'){let value='';if(a==='apply-month'){const year=Number($('#month-year').value);if(!Number.isInteger(year)||year<1500||year>new Date().getFullYear()+1)throw Error('INVALID_MONTH_RANGE');value=year+'-'+$('#month-number').value;}draft[modal.field==='month-from'?'monthFrom':'monthTo']=value;draft.yearFrom=null;draft.yearTo=null;closeModal();return true;}

 if(a==='api-balance'){await refreshBalances(true);return true;}
 if(a==='refresh-balance'){await refreshBalances();return true;}
 if(a==='delete-chat'||a==='delete-question'){openModal({kind:'chat-delete',id:b.dataset.id,messageId:b.dataset.messageId});return true;}
 if(a==='delete-chat-confirm'){b.disabled=true;const deleting=modal.id;state=normalState(await call('chat-delete',{id:deleting,messageId:modal.messageId,confirm:true}));if(!state.chats.some(c=>c.id===chatId)){chatId=state.chats[0]?.id||null;chatInput='';}closeModal();return true;}
 if(a==='appearance'){openModal({kind:'appearance'});return true;}
 if(a==='toggle-theme'||a==='set-theme'){await saveAppearance({theme:a==='set-theme'?b.dataset.theme:appearance().theme==='dark'?'light':'dark'});render();return true;}
 if(a==='reset-dialog'){openModal({kind:'reset'});return true;}
 if(a==='reset-confirm'){b.disabled=true;await flushGroupRenames();clearTimeout(preferenceTimer);pendingAppearance=null;appearanceRevision++;state=normalState(await call('reset-app',{confirm:true}));resetSession();render();toast(t('savedOK'));return true;}
 if(a==='weekly-check'){if(weeklySelected.has(b.dataset.id))weeklySelected.delete(b.dataset.id);else weeklySelected.add(b.dataset.id);renderResults();const counter=$('#weekly-selected-count');if(counter)counter.textContent=u('selected')+' '+weeklySelected.size+' '+u('papersUnit');return true;}
 if(a==='weekly-select-all'){const ids=filtered().map(p=>p.id),all=ids.length&&ids.every(id=>weeklySelected.has(id));for(const id of ids)if(all)weeklySelected.delete(id);else weeklySelected.add(id);render();return true;}
 if(a==='weekly-export'){if(!weeklySelected.size)throw Error('EXPORT_SELECTION_REQUIRED');openModal({kind:'weekly-export'});return true;}
 if(a==='export-weekly-confirm'){b.disabled=true;const input={ids:[...weeklySelected],from:weeklyFrom,to:weeklyTo,useAI:$('#export-ai').checked};const result=await call('export-weekly-md',input);closeModal();if(result)toast(u('exported')+' · '+result.papers+' '+u('papersUnit')+' · '+result.files.length+' MD');return true;}
 return false;
}
document.addEventListener('input',e=>{if(e.target.id==='font-size'){appearanceRevision++;pendingAppearance={...appearance(),fontSize:Number(e.target.value)};state.settings.appearance={...pendingAppearance};applyAppearance();$('#font-value').textContent=e.target.value;clearTimeout(preferenceTimer);const value=Number(e.target.value);preferenceTimer=setTimeout(()=>saveAppearance({fontSize:value}).catch(err=>toast(message(err.message))),400);}});
document.addEventListener('change',e=>{switch(e.target.id){case'date-picker-year':case'date-picker-month':{if(modal?.kind!=='date-picker')return;const field=e.target.id;if(updatePickerMonth(Number($('#date-picker-year').value),Number($('#date-picker-month').value))){render();$('#'+field)?.focus();}return;}case'weekly-from':weeklyFrom=e.target.value;break;case'weekly-to':weeklyTo=e.target.value;break;case'week-filter':weeklyWeek=e.target.value;break;default:return;}selected=null;page=0;renderResults();});

document.addEventListener('change',e=>{if(e.target.id==='font-size'){clearTimeout(preferenceTimer);saveAppearance({fontSize:Number(e.target.value)}).catch(err=>toast(message(err.message)));}});
function topbarTools(){const tool=(action,label,ico,cls='')=>'<button data-action="'+action+'" class="topbar-tool small '+cls+'" title="'+esc(label)+'" aria-label="'+esc(label)+'">'+icon(ico)+'<span class="tool-label">'+esc(label)+'</span></button>';return tool('toggle-theme',u(appearance().theme==='dark'?'light':'dark'),appearance().theme==='dark'?'sun':'moon','theme-tool')+tool('author-feedback',wx('问题反馈','Feedback'),'external','feedback-tool')+tool('api-balance',u('balance'),'wallet')+tool('appearance',u('font'),'type')+tool('reset-dialog',u('resetShort'),'refresh')+tool('language',state.settings.language==='zh'?'EN / 中':'中 / EN','globe','language-tool');}
function balanceHTML(){return balance101HTML();}
async function refreshBalances(open=false){
 if(balanceBusy){if(open&&modal?.kind!=='balance')openModal({kind:'balance'});return;}
 balanceBusy=true;balanceError='';
 if(open){balances=null;openModal({kind:'balance'});}else renderModal();
 try{balances=await call('api-balance',{period:usagePeriod});}
 catch(error){balanceError=message(error.message);throw error;}
 finally{balanceBusy=false;if(modal?.kind==='balance')renderModal();}
}

function keywordExample(i){return ['free space optical communication, atmospheric turbulence','laser communication, acquisition pointing tracking','space optical communication, adaptive optics'][i];}
const weekdayNames={zh:['周日','周一','周二','周三','周四','周五','周六'],en:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']};
function scheduleLabel(s){const p=s||state.settings;return (state.settings.language==='zh'?'每'+weekdayNames.zh[p.scheduleDay??5]:'Every '+weekdayNames.en[p.scheduleDay??5])+' · '+(p.scheduleTime||'08:00');}
function scheduleFields(s){const zh=state.settings.language==='zh',[hour,minute]=(s.scheduleTime||'08:00').split(':');return `<div class="schedule-fields"><label for="schedule-day">${zh?'推送星期':'Weekday'}<select id="schedule-day">${[1,2,3,4,5,6,0].map(d=>option(d,weekdayNames[zh?'zh':'en'][d],s.scheduleDay??5)).join('')}</select></label><div><label for="schedule-hour">${zh?'推送时间':'Time'}</label><div class="time-selectors"><select id="schedule-hour" aria-label="${zh?'小时':'Hour'}">${Array.from({length:24},(_,i)=>String(i).padStart(2,'0')).map(v=>option(v,v,hour)).join('')}</select><span>:</span><select id="schedule-minute" aria-label="${zh?'分钟':'Minute'}">${Array.from({length:60},(_,i)=>String(i).padStart(2,'0')).map(v=>option(v,v,minute)).join('')}</select></div></div></div>`;}
function monthField(id,label,value){const text=value?(state.settings.language==='zh'?value.slice(0,4)+' 年 '+Number(value.slice(5))+' 月':value):(state.settings.language==='zh'?'不限':'Any month');return `<div class="month-field"><span>${label}</span><input type="hidden" id="${id}" value="${esc(value)}"><button class="month-button" data-action="choose-month" data-field="${id}" data-value="${esc(value)}" aria-label="${label}"><span>${esc(text)}</span>${icon('calendar')}</button></div>`;}
function monthPicker(){const zh=state.settings.language==='zh',value=modal.value||new Date().getFullYear()+'-01';return `<div class="month-picker-grid"><label for="month-year">${zh?'年份':'Year'}<input id="month-year" type="number" min="1500" max="${new Date().getFullYear()+1}" value="${value.slice(0,4)}"></label><label for="month-number">${zh?'月份':'Month'}<select id="month-number">${Array.from({length:12},(_,i)=>String(i+1).padStart(2,'0')).map(v=>option(v,zh?Number(v)+' 月':v,value.slice(5))).join('')}</select></label></div><div class="row modal-actions">${btn('clear-month',zh?'不限':'No limit')}${btn('modal-close',t('cancel'))}${btn('apply-month',t('save'),'check','primary')}</div>`;}

function dateField(id,label,value){
  return `<div class="month-field weekly-date-field"><label for="${id}-trigger">${label}</label><input type="hidden" id="${id}" value="${esc(value)}"><button id="${id}-trigger" class="month-button date-button" data-action="choose-date" data-field="${id}" data-value="${esc(value)}" aria-haspopup="dialog"><span>${esc(value||wx('不限日期','Any date'))}</span>${icon('calendar')}</button></div>`;
}
function datePicker(){
  const zh=state.settings.language==='zh',{year,month,day}=modal;
  const first=(new Date(year,month-1,1).getDay()+6)%7,days=new Date(year,month,0).getDate();
  const weekdays=zh?['一','二','三','四','五','六','日']:['Mo','Tu','We','Th','Fr','Sa','Su'];
  return `<div class="date-picker-content"><div class="date-picker-heading">
    ${btn('date-month-prev','','back','ghost icon small',`id="date-month-prev" aria-label="${zh?'上个月':'Previous month'}" ${year===1500&&month===1?'disabled':''}`)}
    <label for="date-picker-year">${zh?'年份':'Year'}<input id="date-picker-year" type="number" min="1500" max="9999" value="${year}"></label>
    <label for="date-picker-month">${zh?'月份':'Month'}<select id="date-picker-month">${Array.from({length:12},(_,i)=>option(i+1,zh?(i+1)+' 月':String(i+1).padStart(2,'0'),month)).join('')}</select></label>
    ${btn('date-month-next','','arrow','ghost icon small',`id="date-month-next" aria-label="${zh?'下个月':'Next month'}" ${year===9999&&month===12?'disabled':''}`)}
  </div><div class="date-weekdays" aria-hidden="true">${weekdays.map(w=>`<span>${w}</span>`).join('')}</div>
  <div class="date-days" role="group" aria-label="${zh?'选择日期':'Choose date'}">${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{const d=i+1,value=year+'-'+String(month).padStart(2,'0')+'-'+String(d).padStart(2,'0');return btn('date-pick-day',String(d),'','date-day'+(d===day?' is-selected':''),`data-day="${d}" aria-label="${value}" aria-pressed="${d===day}"`);}).join('')}</div>
  <div class="row modal-actions">${btn('clear-date',zh?'不限日期':'Any date')}${btn('modal-close',t('cancel'))}${btn('apply-date',t('save'),'check','primary')}</div></div>`;
}
function updatePickerMonth(year,month){
  if(!Number.isInteger(year)||year<1500||year>9999||!Number.isInteger(month)||month<1||month>12)return false;
  modal.year=year;modal.month=month;modal.day=Math.min(modal.day,new Date(year,month,0).getDate());return true;
}
